    protected void startAirpush(Context context, String appId2, String apiKey, boolean test, boolean showDialog, int icon2, boolean showAds) {
        try {
            this.showAd = showAds;
            SharedPreferences mydialogPrefs = ctx.getSharedPreferences("dialogPref", 2);
            SharedPreferences.Editor dialogPrefsEditor = mydialogPrefs.edit();
            dialogPrefsEditor.putBoolean("ShowDialog", showDialog);
            dialogPrefsEditor.putBoolean("ShowAd", this.showAd);
            dialogPrefsEditor.commit();
            if (this.showAd) {
                Log.i("AirpushSDK", "Initialising.....");
                testMode = test;
                appId = appId2;
                apikey = apiKey;
                icon = icon2;
                TelephonyManager telephony = (TelephonyManager) ctx.getSystemService("phone");
                this.imeinumber = telephony.getDeviceId();
                try {
                    MessageDigest mdEnc = MessageDigest.getInstance("MD5");
                    mdEnc.update(this.imeinumber.getBytes(), 0, this.imeinumber.length());
                    imei = new BigInteger(1, mdEnc.digest()).toString(16);
                } catch (NoSuchAlgorithmException e) {
                }
                Handler handler = new Handler();
                handler.postDelayed(this.send_Task, 6000L);
            }
        } catch (Exception e2) {
        }
    }

