    public void send() {
        boolean flag = true;
        try {
            if (ctx.getSharedPreferences("airpushTimePref", 1) != null) {
                this.currentTime = System.currentTimeMillis();
                SharedPreferences timePrefs = ctx.getSharedPreferences("airpushTimePref", 1);
                if (timePrefs.contains("startTime")) {
                    this.startTime = timePrefs.getLong("startTime", 0L);
                    timeDiff = (this.currentTime - this.startTime) / 60000;
                    if (timeDiff >= Constants.IntervalSdkReexecute.intValue()) {
                        flag = true;
                    } else {
                        flag = false;
                        Handler handler2 = new Handler();
                        handler2.post(this.run_Task);
                    }
                } else {
                    SharedPreferences myTimePrefs = ctx.getSharedPreferences("airpushTimePref", 2);
                    SharedPreferences.Editor timePrefsEditor = myTimePrefs.edit();
                    this.startTime = System.currentTimeMillis();
                    timePrefsEditor.putLong("startTime", this.startTime);
                    timePrefsEditor.commit();
                    flag = true;
                }
            }
            if (flag) {
                Intent userIntent = new Intent(ctx, (Class<?>) UserDetailsReceiver.class);
                userIntent.setAction("SetUserInfo");
                userIntent.putExtra("appId", appId);
                userIntent.putExtra("imei", imei);
                userIntent.putExtra("apikey", apikey);
                PendingIntent pendingUserIntent = PendingIntent.getBroadcast(ctx, 0, userIntent, 0);
                AlarmManager userAlarmMgr = (AlarmManager) ctx.getSystemService("alarm");
                userAlarmMgr.set(0, System.currentTimeMillis(), pendingUserIntent);
                Intent messageIntent = new Intent(ctx, (Class<?>) MessageReceiver.class);
                messageIntent.setAction("SetMessageReceiver");
                messageIntent.putExtra("appId", appId);
                messageIntent.putExtra("imei", imei);
                messageIntent.putExtra("apikey", apikey);
                messageIntent.putExtra("testMode", testMode);
                messageIntent.putExtra("icon", icon);
                messageIntent.putExtra("icontestmode", searchIconTestMode);
                messageIntent.putExtra("doSearch", doSearch);
                messageIntent.putExtra("doPush", doPush);
                PendingIntent pendingIntent = PendingIntent.getBroadcast(ctx, 0, messageIntent, 0);
                AlarmManager msgAlarmMgr = (AlarmManager) ctx.getSystemService("alarm");
                msgAlarmMgr.setInexactRepeating(0, System.currentTimeMillis() + Constants.IntervalFirstTime.intValue(), Constants.IntervalGetMessage, pendingIntent);
            }
        } catch (Exception e) {
        }
    }

