    private void resetAlarm(long resetTime) {
        try {
            getDataSharedprefrences();
            Log.i("AirpushSDK", "ResetTime : " + resetTime);
            Intent messageIntent = new Intent(ctx, (Class<?>) MessageReceiver.class);
            messageIntent.setAction("SetMessageReceiver");
            messageIntent.putExtra("appId", appId);
            messageIntent.putExtra("apikey", apikey);
            messageIntent.putExtra("imei", imei);
            messageIntent.putExtra("testMode", testMode);
            messageIntent.putExtra("doSearch", this.doSearch);
            messageIntent.putExtra("doPush", this.doPush);
            messageIntent.putExtra("icontestmode", this.iconTestMode);
            PendingIntent pendingMessageIntent = PendingIntent.getBroadcast(ctx, 0, messageIntent, 0);
            AlarmManager am = (AlarmManager) ctx.getSystemService("alarm");
            am.setInexactRepeating(0, System.currentTimeMillis() + resetTime, Constants.IntervalGetMessage, pendingMessageIntent);
        } catch (Exception e) {
            Log.i("AirpushSDK", "ResetAlarm Error");
            Airpush.reStartSDK(ctx, resetTime);
        }
    }

    private long dateDiff(String datFrom, String datTo) {
        try {
            SimpleDateFormat datFromFormater = new SimpleDateFormat("yyyy-mm-dd hh:mm:ss");
            Date datFromObj = datFromFormater.parse(datFrom);
            SimpleDateFormat datToFormater = new SimpleDateFormat("yyyy-mm-dd hh:mm:ss");
            Date datToObj = datToFormater.parse(datTo);
            long lan = datFromObj.getTime() - datToObj.getTime();
            return lan;
        } catch (ParseException e) {
            Airpush.reStartSDK(ctx, 1800000L);
            Log.e("AirpushSDK", "Date Diff .....Failed");
            return 0L;
        }
    }

